const b = ($json.body !== undefined) ? $json.body : $json;
const produtoNomeOuId = (b.produto_nome_ou_id || '').toString().trim();
const quantidade = parseInt(b.quantidade, 10);
if (!produtoNomeOuId || !Number.isInteger(quantidade) || quantidade < 1) {
  return [{ json: { _erro: 'parametros_invalidos', encontrado: false } }];
}
return [{ json: { produto_nome_ou_id: produtoNomeOuId, quantidade } }];

const entrada = $('Validar Entrada Preco').first().json;
const items = $input.all().map(i => i.json).filter(p => p && p.id);
return [{ json: { ...entrada, achou_por_id: items.length > 0, produto: items[0] || null } }];

const quantidade = $('Validar Entrada Preco').first().json.quantidade;
const entrada = $json;
let produto = entrada.produto || null;
if (!produto) {
  const items = $input.all().map(i => i.json).filter(p => p && p.id);
  produto = items[0] || null;
}
if (!produto) return [{ json: { encontrado: false } }];
return [{ json: { encontrado: true, produto_id: produto.id, produto_nome: produto.nome, categoria: produto.categoria, quantidade } }];

const resp = $json;
const body = resp.body || {};
if (resp.statusCode >= 400 || !body.calculo) {
  return [{ json: { encontrado: false, erro: body.error || 'erro_ao_calcular' } }];
}
const produto = body.produto;
const c = body.calculo;
const nomeFmt = (produto.nome || '').toUpperCase();
let fraseValor = `R$ ${c.valorFinal.toFixed(2).replace('.', ',')}`;
if (c.descontoPct > 0) fraseValor += ` (${c.descontoPct}% de desconto aplicado)`;
const qtdTxt = c.quantidade > 1 ? ` (qtd: ${c.quantidade})` : '';
const frase_pronta = `${nomeFmt}${qtdTxt}, ${fraseValor}`;
return [{ json: {
  encontrado: true,
  produto_id: produto.id,
  produto_nome: produto.nome,
  valor_unitario: c.valorUnitario,
  quantidade: c.quantidade,
  desconto_pct: c.descontoPct,
  valor_final: c.valorFinal,
  frase_pronta,
} }];

const MOTIVOS = ["dizu", "alto_toque", "negociacao_pagamento", "ambiguo_nao_resolvido", "proposta_negada", "timeout", "nao_entendido", "cancelamento_pago", "cancelamento_entregue", "outro"];
const b = ($json.body !== undefined) ? $json.body : $json;
const telefone = (b.telefone || '').toString().trim();
const motivo = (b.motivo || '').toString().trim();
if (!telefone || !MOTIVOS.includes(motivo)) {
  return [{ json: { _erro: 'parametros_invalidos', telefone, motivo } }];
}
return [{ json: { telefone, motivo } }];

const entrada = $('Validar Entrada Escalar').first().json;
const sessoes = $input.all().map(i => i.json).filter(s => s && s.id);
const sessao = sessoes[0] || null;
return [{ json: {
  telefone: entrada.telefone,
  motivo: entrada.motivo,
  has_session: !!sessao,
  sessao_id: sessao ? sessao.id : null,
  dados_extra_atual: sessao ? (sessao.dados_extra || {}) : {},
} }];

const motivo = $('Escalar: Preparar Gravacao').first().json.motivo;
const frase_pronta = motivo === 'dizu'
  ? 'Esse numero aqui e so da JS Grafica agora. Pra pedido de comida da Dizu Refeicoes, chama direto no WhatsApp delas: (81) 9107-0806 \ud83d\ude0a'
  : 'Chamando a equipe';
return [{ json: { ok: true, frase_pronta } }];

const b = ($json.body !== undefined) ? $json.body : $json;
const telefone = (b.telefone || '').toString().trim();
if (!telefone) {
  return [{ json: { _erro: 'parametros_invalidos' } }];
}
const janelaMs = 7 * 24 * 60 * 60 * 1000;
return [{ json: { telefone, desde_ms: $now.toMillis() - janelaMs } }];

const body = $input.first().json;
const rows = Array.isArray(body) ? body : (body ? [body] : []);

// Deteccao Dizu em 2 niveis, MESMA logica de 'Dizu: Verificar Padrao' (demanda 316) - mantida
// IDENTICA de proposito, nao criar copia que pode divergir com o tempo. Regex flat anterior
// (demanda 315) dava falso positivo em clientes pagantes pedindo cardapio IMPRESSO; ver 316.
function isDizuMessage(texto) {
  const altaPrecisao = /quentinha|bolinho de frango|\blombo\b|farofa|vinagrete|panqueca de carne|frango pizzaiolo|peixe frito|bife ao molho|cupim molho|prato feito|prato do dia|pre[çc]o d[ao] marmita/;
  if (altaPrecisao.test(texto)) return true;

  const ambigua = /card[áa]pio|almo[çc]o|marmita|refei[çc][ãa]o|\bprato\b|\bcomida\b/;
  if (!ambigua.test(texto)) return false;

  const temIntencaoPedido = /quero (um|uma)|vou querer|tem\s.{0,15}ainda|ainda tem|faz entrega|vcs? entreg|voc[êe]s? entreg|qual\s.{0,15}card[áa]pio|card[áa]pio\s.{0,10}hoje|hoje\s.{0,10}tem/;
  if (!temIntencaoPedido.test(texto)) return false;

  const temVocabGrafico = /imprim|papel\s*(cart[ãa]o|foto|of[íi]cio|couch[eê])|plastific|frente e verso|\barte\b|\bdesign\b|\bpdf\b|qr\s*code|adesivo|cart[ãa]o de visita|or[çc]amento|vende[- ]se/;
  if (temVocabGrafico.test(texto)) return false;

  return true;
}

const semDizu = rows.filter(r => {
  const texto = (((r.message_text || '') + ' ' + (r.caption || '')).toLowerCase());
  return !isDizuMessage(texto);
});

return semDizu.map(r => ({ json: r }));

const sessoes = ($('Contexto: Buscar Sessao').all() || []).map(i => i.json).filter(s => s && s.id);
const ultima = sessoes[0] || null;
const escalada = !!(ultima && ultima.status === 'escalada');
const sessaoAtiva = (ultima && !escalada) ? ultima : null;

const logs = $input.all().map(i => i.json).filter(l => l && l.phone);
logs.sort((a, b) => (b.data_timestamp || 0) - (a.data_timestamp || 0));
const contexto_recente = logs.map(l => ({
  // Demanda 318: quando a mensagem historica era resposta a outra (quoted_msg_id), prepende
  // o texto citado (coluna quoted_msg_body, resolvida na demanda 318 no ramo de log do
  // workflow 01 - antes ficava sempre null). Mesma convencao de fallback ja usada aqui.
  texto: (l.quoted_msg_body ? '[respondendo a: "' + l.quoted_msg_body + '"] ' : '') + (l.message_text || l.caption || '[midia sem legenda]'),
  quando: l.sent_at || (l.data_timestamp ? new Date(l.data_timestamp).toISOString() : null),
  origem: l.from_me ? (l.enviado_por || 'sistema') : 'cliente',
}));

return [{ json: {
  sessao_ativa: sessaoAtiva,
  contexto_recente,
  ultima_interacao_foi_escalada: escalada,
} }];

const b = ($json.body !== undefined) ? $json.body : $json;
const texto = (((b.message_text || '') + ' ' + (b.caption || '')).toLowerCase());

// Deteccao Dizu em 2 niveis (demanda 316) - regex flat anterior dava falso positivo real
// em clientes pagantes da grafica pedindo cardapio IMPRESSO (Thalita, 8 pedidos reais) e
// placa com nome de comida (picole, 1 pedido real). MESMA logica replicada em 'Contexto:
// Buscar Log Recente' (comentario la deixa isso explicito) - manter as 2 em sincronia manual.
function isDizuMessage(texto) {
  const altaPrecisao = /quentinha|bolinho de frango|\blombo\b|farofa|vinagrete|panqueca de carne|frango pizzaiolo|peixe frito|bife ao molho|cupim molho|prato feito|prato do dia|pre[çc]o d[ao] marmita/;
  if (altaPrecisao.test(texto)) return true;

  const ambigua = /card[áa]pio|almo[çc]o|marmita|refei[çc][ãa]o|\bprato\b|\bcomida\b/;
  if (!ambigua.test(texto)) return false;

  const temIntencaoPedido = /quero (um|uma)|vou querer|tem\s.{0,15}ainda|ainda tem|faz entrega|vcs? entreg|voc[êe]s? entreg|qual\s.{0,15}card[áa]pio|card[áa]pio\s.{0,10}hoje|hoje\s.{0,10}tem/;
  if (!temIntencaoPedido.test(texto)) return false;

  const temVocabGrafico = /imprim|papel\s*(cart[ãa]o|foto|of[íi]cio|couch[eê])|plastific|frente e verso|\barte\b|\bdesign\b|\bpdf\b|qr\s*code|adesivo|cart[ãa]o de visita|or[çc]amento|vende[- ]se/;
  if (temVocabGrafico.test(texto)) return false;

  return true;
}

return [{ json: { is_dizu: isDizuMessage(texto) } }];

const b = ($json.body !== undefined) ? $json.body : $json;
const telefone = (b.telefone || '').toString().trim();
const produto_id = (b.produto_id || '').toString().trim();
const quantidade = parseInt(b.quantidade, 10);
if (!telefone || !produto_id || !Number.isInteger(quantidade) || quantidade < 1) {
  return [{ json: { _erro: 'parametros_invalidos' } }];
}
return [{ json: { telefone, produto_id, quantidade } }];

const entrada = $('CriarPedido: Validar Entrada').first().json;
const autorizado = $input.all().some(i => i.json && i.json.telefone);
return [{ json: { ...entrada, autorizado } }];

const entrada = $('CriarPedido: Avaliar Whitelist').first().json;
const sessoes = $input.all().map(i => i.json).filter(s => s && s.id);
const sessao = sessoes[0] || null;
let dizuBloqueado = false;
if (sessao && sessao.status === 'escalada') {
  const de = sessao.dados_extra || {};
  if (de.motivo_escalonamento === 'dizu') dizuBloqueado = true;
}
return [{ json: { ...entrada, sessao_id: sessao ? sessao.id : null, dizu_bloqueado: dizuBloqueado } }];

const entrada = $('CriarPedido: Avaliar Trava Dizu').first().json;
const duplicado = $input.all().some(i => i.json && i.json.id);
return [{ json: { ...entrada, duplicado } }];

const entrada = $('CriarPedido: Avaliar Duplicidade').first().json;
const resp = $json;
const body = resp.body || {};
if (resp.statusCode >= 400 || body.encontrado === false) {
  return [{ json: { ...entrada, produto_encontrado: false } }];
}
return [{ json: {
  ...entrada,
  produto_encontrado: true,
  servico_nome: body.produto_nome,
  valor_unitario: body.valor_unitario,
  desconto_pct: body.desconto_pct,
  valor_final: body.valor_final,
} }];

const d = $json;
const valorTotal = Math.round(d.valor_unitario * d.quantidade * 100) / 100;
return [{ json: { ...d, valor_total: valorTotal } }];

const p = $json;
const valorTexto = p.desconto_pct > 0
  ? `R$ ${Number(p.valor_final).toFixed(2).replace('.', ',')} (${p.desconto_pct}% de desconto aplicado)`
  : `R$ ${Number(p.valor_final).toFixed(2).replace('.', ',')}`;
const qtdTexto = p.quantidade > 1 ? `\nQtd: ${p.quantidade}` : '';
const frase_pronta = `Pedido confirmado!\n\n${p.servico_nome}${qtdTexto}\n${valorTexto}\n\nAssim que confirmarmos o pagamento, a gente comeca a producao.`;
return [{ json: {
  pedido_id: p.id,
  servico_nome: p.servico_nome,
  valor_final: p.valor_final,
  frase_pronta,
} }];

const b = ($json.body !== undefined) ? $json.body : $json;
const pedido_id = (b.pedido_id || '').toString().trim();
if (!pedido_id) return [{ json: { _erro: 'parametros_invalidos' } }];
return [{ json: { pedido_id } }];

const entrada = $('Pix: Validar Entrada').first().json;
const pedidos = $input.all().map(i => i.json).filter(p => p && p.id);
const pedido = pedidos[0] || null;
if (!pedido) return [{ json: { ...entrada, situacao: 'nao_encontrado' } }];
if (pedido.forma_pagamento_escolhida !== 'pix') return [{ json: { ...entrada, situacao: 'sem_pix_escolhido' } }];
return [{ json: { ...entrada, situacao: 'ok', telefone: pedido.telefone, valor_final: pedido.valor_final } }];

const entrada = $('Pix: Avaliar Pedido').first().json;
const resp = $('Pix: Gerar Cobranca Real').first().json;
const body = resp.body || {};
const ok = resp.statusCode < 400 && !!body.qrCode;
if (!ok) return [{ json: { ...entrada, cobranca_ok: false } }];
return [{ json: {
  ...entrada,
  cobranca_ok: true,
  copia_e_cola: body.qrCode,
  expira_em: body.expiraEm,
  valor: body.valor,
} }];

const d = $json;
const valorTxt = Number(d.valor).toFixed(2).replace('.', ',');
const frase_pronta = `Para iniciarmos a producao, precisamos do pagamento antecipado

Pix copia e cola (valido por 24h):

${d.copia_e_cola}

Valor: R$ ${valorTxt}

E so copiar o codigo acima e colar na area Pix do app do seu banco. Assim que o pagamento cair, a gente avisa por aqui.`;
return [{ json: { copia_e_cola: d.copia_e_cola, expira_em: d.expira_em, frase_pronta } }];

const b = ($json.body !== undefined) ? $json.body : $json;
const pedido_id = (b.pedido_id || '').toString().trim();
const telefone = (b.telefone || '').toString().trim();
if (!pedido_id || !telefone) return [{ json: { _erro: 'parametros_invalidos' } }];
return [{ json: { pedido_id, telefone } }];

const entrada = $('Cancelar: Validar Entrada').first().json;
const pedidos = $input.all().map(i => i.json).filter(p => p && p.id);
const pedido = pedidos[0] || null;
if (!pedido) return [{ json: { ...entrada, situacao: 'nao_encontrado' } }];
if (pedido.telefone !== entrada.telefone) return [{ json: { ...entrada, situacao: 'nao_pertence' } }];
const pago = !!pedido.pagamento_confirmado;
const entregue = !!pedido.data_entregue_at || pedido.status === 'entregue';
let acao;
if (!pago) acao = 'cancelar_direto';
else if (pago && !entregue) acao = 'escalar_devolucao';
else acao = 'escalar_admin_pos_entrega';
return [{ json: { ...entrada, situacao: 'ok', acao } }];

// Demanda 305: gate deterministico de Alto Toque (dado pessoal), mesmo
// regex real ja corrigido no 206 (Servico Alto Toque?, pos-278: inclui
// gov.br/conta gov/senha do gov), agora testado direto contra o texto cru
// da mensagem (o 206 testa contra uma classificacao previa do Gemini que
// nao existe neste pipeline mais simples).
const b = ($json.body !== undefined) ? $json.body : $json;
const texto = ((b.message_text || '') + ' ' + (b.caption || '')).toLowerCase();
const re = /curr[ií]culo|digita[çc][ãa]o|prova|antecedente|foto composta|composi[çc][ãa]o|gov\.?br|conta gov|senha do gov/i;
return [{ json: { is_alto_toque: re.test(texto) } }];
